fn main() { println!("Trigram Test"); let c = rusqlite::Connection::open_in_memory().unwrap(); c.execute("CREATE VIRTUAL TABLE t USING fts5(text, tokenize='trigram')", []).unwrap(); c.execute("INSERT INTO t(text) VALUES ('læssemaskiner')", []).unwrap(); let mut stmt = c.prepare("SELECT text FROM t WHERE text MATCH 'maskine'").unwrap(); let mut rows = stmt.query([]).unwrap(); while let Some(row) = rows.next().unwrap() { println!("Match: {}", row.get::<_, String>(0).unwrap()); } }
